abstract class WashType{public abstract String getName();public abstract int getDuration();public abstract double getCharge();}class QuickWash extends WashType{public String getName(){return "Quick";}public int getDuration(){return 30;}public double getCharge(){return 20;}}class NormalWash extends WashType{public String getName(){return "Normal";}public int getDuration(){return 45;}public double getCharge(){return 30;}}class HeavyWash extends WashType{public String getName(){return "Heavy";}public int getDuration(){return 60;}public double getCharge(){return 45;}}class Student{String name;Student(String n){name=n;}}class WashCycle{Student student;WashingMachine machine;WashType type;WashCycle(Student s,WashingMachine m,WashType t){student=s;machine=m;type=t;}}
class WashingMachine{private String id;private WashCycle currentCycle;WashingMachine(String i){id=i;}public boolean isFree(){return currentCycle==null;}public void startWash(Student s,WashType t){if(!isFree()){System.out.println("Machine "+id+" is currently busy.");return;}currentCycle=new WashCycle(s,this,t);System.out.printf("%s wash started on %s for %s (%d min). Charge: ₹%.2f.%n",t.getName(),id,s.name,t.getDuration(),t.getCharge());}public void completeCycle(){if(isFree()){System.out.println(id+" is already free.");return;}System.out.println(id+" cycle completed.");currentCycle=null;System.out.println(id+" is now free.");}}
public class HostelLaundryQueue{public static void main(String[] args){Student a=new Student("Asha"),r=new Student("Ravi"),n=new Student("Neha");WashingMachine m1=new WashingMachine("M1"),m2=new WashingMachine("M2");m1.startWash(a,new QuickWash());m1.startWash(r,new HeavyWash());m2.startWash(r,new HeavyWash());m1.completeCycle();m1.startWash(n,new NormalWash());}}